function reserve(stock, items) {
  for (const { sku, quantity } of items) {
    const left = stock.get(sku);
    if (left === undefined) throw new Error(`No product ${sku}`);
    if (quantity > left) throw new Error(`Only ${left} of ${sku} left`);
  }
  for (const { sku, quantity } of items) stock.set(sku, stock.get(sku) - quantity);
}

