const stock = new Map([["RICE-5KG", 3]]);
const reserve = (order) => stock.set(order.sku, stock.get(order.sku) - order.quantity);
const release = (order) => stock.set(order.sku, stock.get(order.sku) + order.quantity);

async function checkout(order, charge) {
  reserve(order);
  const payment = await charge(order);
  if (payment.status === "declined") {
    release(order);
    return { status: "cancelled", reason: payment.reason };
  }
  return { status: "paid" };
}

const approve = async () => ({ status: "succeeded", chargeId: "ch_1" });
const decline = async () => ({ status: "declined", reason: "insufficient funds" });
console.log(await checkout({ sku: "RICE-5KG", quantity: 2 }, approve), stock.get("RICE-5KG"));
console.log(await checkout({ sku: "RICE-5KG", quantity: 1 }, decline), stock.get("RICE-5KG"));

