const products = [{ sku: "RICE-5KG", name: "Rice 5kg" }, { sku: "OIL-1L", name: "Palm oil 1L" }];
const orders = [{ id: 1, status: "paid" }, { id: 2, status: "cancelled" }];
const lines = [
  { orderId: 1, sku: "RICE-5KG", quantity: 2 },
  { orderId: 1, sku: "OIL-1L", quantity: 1 },
  { orderId: 2, sku: "OIL-1L", quantity: 4 },
];

const nameOf = new Map(products.map((product) => [product.sku, product.name]));
for (const order of orders) {
  const items = lines
    .filter((line) => line.orderId === order.id)
    .map((line) => ({ name: nameOf.get(line.sku), quantity: line.quantity }))
    .sort((a, b) => a.name.localeCompare(b.name))
    .map((item) => `${item.quantity} x ${item.name}`);
  console.log(`#${order.id} ${order.status}: ${items.join(", ")}`);
}
